<?php
namespace App\Models;
use Illuminate\Database\Eloquent\Model;
class AttendancePayrollSummary extends Model { protected $fillable=['attendance_payroll_period_id','user_id','company_id','branch_id','division_id','department_id','section_id','unit_id','designation_id','employment_type_id','working_days','payable_days','present_days','absent_days','paid_leave_days','unpaid_leave_days','weekly_off_days','holiday_days','half_days','unpaid_absence_days','deduction_days','final_payable_days','late_occurrences','late_minutes','early_out_occurrences','early_out_minutes','overtime_hours','status','finalized_at','finalized_by']; protected $casts=['working_days'=>'decimal:2','payable_days'=>'decimal:2','present_days'=>'decimal:2','absent_days'=>'decimal:2','paid_leave_days'=>'decimal:2','unpaid_leave_days'=>'decimal:2','weekly_off_days'=>'decimal:2','holiday_days'=>'decimal:2','half_days'=>'decimal:2','unpaid_absence_days'=>'decimal:2','deduction_days'=>'decimal:2','final_payable_days'=>'decimal:2','overtime_hours'=>'decimal:2','finalized_at'=>'datetime']; public function period(){return $this->belongsTo(AttendancePayrollPeriod::class,'attendance_payroll_period_id');} public function employee(){return $this->belongsTo(User::class,'user_id');} }
